// ❌ OLD: A self-referential struct holds a pointer to one of its OWN
// fields. If the struct is MOVED, the pointer still points at the OLD
// address — a dangling pointer. (This example is illustrative; in safe
// Rust you can't even construct this without unsafe, which is the
// point.)
struct SelfRef {
    data: String,
    ptr_to_data: *const String, // ❌ OLD: points into `self`
}

fn build() -> SelfRef {
    let mut s = SelfRef {
        data: String::from("hello"),
        ptr_to_data: std::ptr::null(),
    };
    s.ptr_to_data = &s.data as *const String; // points to own field
    s
}

