// ✅ NEW: The async runtime uses Pin to keep futures immovable while
// they may be polled. An async block that borrows a local across an
// await is self-referential; polling it through Pin keeps the internal
// pointers valid.
use std::pin::Pin;

async fn example() {
    let data = String::from("hello");
    // The compiler may turn `data` into a field and a self-reference
    // to it inside the generated future — self-referential.
    tokio::time::sleep(std::time::Duration::from_millis(1)).await;
    println!("{data}"); // borrows `data` across the await
}

// The executor polls:
//   let mut fut = Box::pin(example());  // ✅ NEW: pinned, immovable
//   let waker = ...; let mut cx = Context::from_waker(&waker);
//   let _ = fut.as_mut().poll(&mut cx); // poll takes Pin<&mut Self>

